export type DataMeetAdminWard = {
  num: number;
  name: string;
  nameMarathi: string;
  code: string;
  address: string;
  helpline: string;
  electoralWards: readonly number[];
  lat: number;
  lon: number;
  areasCovered: readonly string[];
  boundary: readonly (readonly [number, number])[];
};

export type DataMeetPcmcWard = {
  name: string;
  wardnum: number | string;
  boundary: readonly (readonly [number, number])[];
};

export type DataMeetPcmcZone = {
  zoneKey: string;
  name: string;
  nameMarathi: string;
  headquarters: string;
  helpline: string;
  electoralWards: readonly DataMeetPcmcWard[];
};

